'use strict';
// Standalone design-state demonstration. No imports, fetches, storage, or game connections.
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const params=new URLSearchParams(location.search);
let S,trail=[],dialog=null,originFocus=null,timer=null,saveTimer=null,actionTimer=null;
const notes={home:['V01 · The lot is home','A 80px persistent HUD owns date, pause, cash and campaign identity. It is not a second memo panel.','B 290px right rail exposes exceptions and named films. The early state has one film; the mature state grows by rows.','C 410px selected-object card anchors an explicit Open action. Select never spends.','D 60px global navigation reaches the same entity owners; the schematic lot is original illustration.'],production:['V02 · One film, one decision','A Identity and closed production state stay in a pinned header. Progress denotes phases, not a fabricated completion percentage.','B The 245px companion column contains exact people/worksite links. Main detail scrolls; excursions retain film and offset.','C The footer pins action + authoritative reason + response together (F1). Waiting never becomes a fake remedy.','D “Schedule the shooting take” represents the existing operation. All receipts here are simulated.'],person:['V03 · Retained-lot dossier','A The silhouette is an original placeholder, not a real person or borrowed art. Person ID distinguishes duplicate names.','B Perceived role OVR, availability and existing cost categories are kept together. Specialty bars require a safe read-model extension.','C Inspection and Review contract are distinct. The latter exposes signing, payroll, overhead and term before commitment.','D Back returns to the originating film or casting draft, with scroll and focus.'],casting:['V04 · Compare without losing the role','A Left company rail retains the draft while the selected role drives candidate facts.','B Aligned comparison shows the same attributes and fee basis for each person. Unavailable candidates remain inspectable.','C Review this candidate returns to an exact dossier. Pins and company choices remain intact (F6).','D Greenlight consequence review retains the authoritative queued/formed distinction; the mock does not simulate admission.'],building:['V05 · Place, review, build','A Catalogue selection opens a footprint preview; a pointer/keyboard alternative is specified. This schematic grid only changes design state.','B Exact quote fields group cost, timing, capacity and cash after. Conflicting constraints are listed together.','C Cancel clears an uncommitted tool, not a submitted construction job. Construction and operation are different states.','D Lab entry inherits this card hierarchy; its department workflow remains P13B-owned.'],finance:['V06 · The same studio, deeper evidence','A Finance period and coverage explain what the summary includes. Conditional runway is never a forecast guarantee.','B Drill-down routes retain the exact origin; Industry shows only public records and public gross.','C One shared text preference is a proposed common behavior, not a claim of current implementation.','D No loan, valuation, net-worth or private-rival data is invented.'],campaigns:['V07 · Know which world you keep','A Active record and selected target have distinct labels. All records are in-memory fixtures.','B Unnamed leave review leads directly to Save As. Name, copy activation and form-draft loss are reviewed explicitly.','C Pending / unresolved / simulated receipt are separate. Close view cannot cancel a submitted operation.','D Continue to the original leave task requires a new explicit review; there is no silent replay.'],result:['V08 · Tell the film’s story','A Critics, audience and business carry separate meanings. Actual receipts and the frozen forecast are labeled.','B A record without evidence says unavailable; zero is not substituted.','C Exact company and history routes retain origin. Historical records keep their attribution.','D Film-poster graphics are original placeholders; no game/manual art is reproduced.'],components:['C01 · Components and tokens','A Warm opaque paper protects reading over the lot. Pine-green carries primary actions; brass is a restrained accent.','B States use text and shape as well as color. Focus is a 3px blue ring with 3px offset.','C Minimum control height 44px, padding 9×16px; 8px spacing grid with 4px optical adjustments.','D The specification records contrast and input rules. No broad accessibility compliance is claimed.'],alternatives:['D00 · Direction selection','A “Studio desk” keeps contextual surfaces at the edges of a usable lot. This is the selected direction.','B “Permanent ledger” gives dense management a permanent left column, but reduces world space and implies a dashboard home.','C Larger workspaces remain deliberate in the selected direction. Both compositions are original mockups.','D Only direction A is developed into the eight families.']};
function reset(){clearTimeout(timer);clearTimeout(saveTimer);clearTimeout(actionTimer);S={screen:params.get('screen')||'home',variant:params.get('state')||'mature',person:'mara',from:'',draft:'Celia Ward',cash:'$2,480,000',campaign:'Unnamed current campaign',selected:'Harbor — rehearsal',name:'Harbor — new cut',outcome:'success',prod:'ready',text:Number(params.get('text')||100),paused:true,comparison:false,selectedFacility:'stage',placement:'valid',notice:'',saveStatus:'idle',actionBusy:false,castStatus:'draft',signed:false,actionReceipt:''};trail=[];dialog=null;$('#modal-root').innerHTML='';$('#game').inert=false;render();const v=S.variant;if(v==='contract'){S.person='celia';render();modal('contract');}if(['leave','name','overwrite','pending','unresolved','receipt','continue'].includes(v)&&S.screen==='campaigns'){modal(v);if(['pending','unresolved','receipt'].includes(v)){S.saveStatus=v==='receipt'?'success':v;if(v==='receipt')S.campaign=S.name;render();}}if(S.screen==='casting'&&v==='compare'){S.comparison=true;render();}}
const btn=(text,act,cls='',disabled=false)=>`<button class="${cls}" data-act="${act}" ${disabled?'disabled':''}>${text}</button>`;
const badge=(text,kind='')=>`<span class="badge ${kind}">${text}</span>`;
const kv=rows=>`<dl class="kv">${rows.map(([a,b])=>`<div><dt>${a}</dt><dd>${b}</dd></div>`).join('')}</dl>`;
const portrait=()=>`<div class="portrait" aria-label="Original silhouette placeholder"><svg viewBox="0 0 110 150" aria-hidden="true"><ellipse cx="55" cy="46" rx="24" ry="29" fill="#53695b"/><path d="M31 42q0-37 26-34q29 0 29 39l-10-16q-14 6-38-2z" fill="#324f43"/><path d="M8 150l4-43q2-24 29-29l14 18l14-18q29 7 30 31l4 41" fill="#3d5d4d"/><path d="M42 81l13 15l14-15l-8 49H51z" fill="#dedac7"/></svg><small>PORTRAIT PLACEHOLDER</small></div>`;
const idline=(txt)=>`<span class="eyebrow">${txt}</span>`;
function hud(){return `<header class="hud"><div class="brand">STUDIO<small>WESTHAVEN PICTURES · FICTIONAL</small></div><div class="hud-group"><div class="date"><strong>1926 · Week 12</strong><small>Campaign calendar</small></div>${btn(S.paused?'Ⅱ Paused':'▶ Running preview','pause','active')}${btn('1×','speed')}${btn('2×','speed')}${btn('4×','speed')}</div><div class="money"><strong class="mono">${S.cash}</strong><small>Available cash · mock amount</small></div><div><div class="eyebrow">Active campaign</div>${btn(S.campaign==='Unnamed current campaign'?'Unnamed · Unsaved':esc(S.campaign),'campaigns','quiet')}${S.saveStatus!=='idle'?btn('Save As · '+S.saveStatus,'save-status','status-link'):''}</div></header>`;}
const navItems=[['home','Lot','◇'],['production','Productions','▤'],['casting','Casting','◉'],['person','People','♙'],['building','Facilities','▱'],['finance','Finance','≡'],['industry','Industry','◎'],['campaigns','Menu','☰']];
function nav(){const current=S.screen==='finance'&&['industry','drill'].includes(S.variant)?'industry':S.screen;return `<nav class="nav" aria-label="Studio">${navItems.map(([id,label,mark])=>btn(`<span class="nav-mark">${mark}</span>${label}`,id,current===id?'current':'')).join('')}</nav>`;}
function work(code,title,sub,body,footer='',wide=false){return `<div class="scene-name">Westhaven Pictures<small>Original schematic lot</small></div><section class="surface work ${wide?'wide':''}" aria-label="${esc(title)}"><header class="work-head"><div>${idline(code)}<h1>${title}</h1><p>${sub}</p></div><div class="head-actions">${btn('‹ Back','back')}</div></header><div class="work-body" id="scroll">${body}</div>${footer?`<footer class="work-foot">${footer}</footer>`:''}</section>`;}
function responseTools(){return `<div class="preferences" style="margin-top:20px"><small>PROTOTYPE RESPONSE FIXTURE</small><label>Next response <select id="outcome"><option value="success" ${S.outcome==='success'?'selected':''}>Simulated success</option><option value="refusal" ${S.outcome==='refusal'?'selected':''}>Simulated refusal</option><option value="unresolved" ${S.outcome==='unresolved'?'selected':''}>Unresolved / retry</option></select></label></div>`;}
function home(){const early=S.variant==='early';return `<div class="surface attention">${badge('! Action needed','warn')}<strong>${early?'Your first screenplay is ready':'One film needs a scheduling decision'}</strong><small>${early?'Review its cast before committing a budget.':'The Glass Harbor · Stage 07 · no time advances on selection.'}</small></div>${btn('◎ Stage 07 · selected','production','lot-pin')}<aside class="surface rail"><div class="eyebrow">Your pictures</div><h2>${early?'The first production':'On the studio lot'}</h2>${btn(`<strong>${early?'The Long Way Home':'The Glass Harbor'}</strong><small>${early?'Ready for casting':'! Take ready to schedule'}</small>`,early?'casting':'production','choice selected')}${early?'':btn('<strong>After the Rain</strong><small>◷ Waiting for Post</small>','wait','choice')}${early?'':btn('<strong>The Long Way Home</strong><small>Script ready · cast the lead</small>','casting','choice')}${early?'':btn('<strong>A Summer in Red</strong><small>Released · inspect result</small>','result','choice')}<div class="rule"></div><small>${early?'6 people · 1 project':'24 people · 4 projects'}</small>${btn('Inspect Mara Vale · Director','profile-mara','text-link')}</aside><section class="surface home-card">${idline('SELECTED FACILITY · STAGE-07')}<h1>Soundstage 07</h1>${badge('● Operational')}<p>${early?'Ready to welcome your first company.':'The Glass Harbor occupies this stage. The next shooting take is ready to schedule.'}</p><div class="actions">${btn(early?'Review the screenplay':'Open production',early?'casting':'production','primary')}${btn('Inspect facility','facility-detail')}</div></section><div class="lot-caption">V01 · ${early?'Early / simple':'Mature / multi-project'} fixture · ${btn(early?'Show mature lot':'Show early lot',early?'mature':'early','quiet')}</div>`;}
function production(){const waiting=S.variant==='waiting',missing=S.variant==='missing';const status=waiting?'Wrapped · waiting for Post':S.prod==='success'?'Take scheduled':S.prod==='pending'?'Submitting schedule…':S.prod==='refusal'?'Scheduling refused':'Take ready to schedule';const company=`<h2 class="section-title">Company</h2>${[['Mara Vale','Director · contracted','profile-mara'],['Celia Ward','Lead · one-picture fee','profile-celia'],['Mara Vale','Craft lead · P-022','profile-duplicate']].map(([n,r,a])=>`<div class="listrow"><div><strong>${n}</strong><small>${r}</small></div>${btn('Profile ›',a,'quiet')}</div>`).join('')}<h2 class="section-title" style="margin-top:24px">Worksites</h2>${btn(waiting?'Production Post ›':'Soundstage 07 ›','facility-detail','choice')}<small>Locate inspects the exact building.</small>`;
let body=`<div class="split"><aside>${company}</aside><div><div class="row between"><h2 class="section-title">${waiting?'Principal photography wrapped':'Shooting · the next decision'}</h2>${badge(waiting?'◷ Normal waiting':'! Your decision',waiting?'':'warn')}</div><div class="progress">${Array.from({length:6},(_,i)=>`<span class="${i<(waiting?4:3)?'done':''}"></span>`).join('')}</div><div class="milestones"><span>Script</span><span>Cast</span><span>Shoot</span><span>Post</span><span>Release</span></div><div class="rule"></div><div class="note"><strong>${waiting?'Post capacity is occupied':'Stage 07 is ready for the company'}</strong>${waiting?'After the Rain has wrapped. The Post facility is occupied by another film; no immediate remedy is offered in this fixture.':'The set and company are ready. Put this take on the weekly schedule to allow work to proceed.'}<p><small>Payroll and studio overhead continue each week. This view does not advance the calendar.</small></p></div><div class="rule"></div><h2 class="section-title">Supporting information</h2>${kv([['Film identity',waiting?'FILM-018':'FILM-014'],['Current method','Silent'],['Current worksite',waiting?'Awaiting Post capacity':'Soundstage 07'],['Completion',waiting?'No firm completion date':'Conditional on scheduled work']])}<div style="margin-top:24px">${btn('Inspect supporting facility','facility-detail')}${btn('Show no-remedy waiting case','wait','quiet')}${btn('Show missing-target case','missing','quiet')}</div><div class="rule"></div><h2 class="section-title">The return context</h2><p>Keep this film, its place in the project list and this detail position when inspecting a company member or worksite.</p><small>Scroll here, open a profile, then use Back to check the prototype’s retained position.</small>${responseTools()}</div></div>`;
if(missing)body=`<div class="empty"><h2>This exact production is unavailable</h2><p>FILM-014 no longer resolves in this fixture. Your previous selection has not been replaced.</p>${btn('Return to original film fixture','production','primary')}</div>`;
let f=waiting?`<div><strong>◷ Waiting for Post capacity</strong><small>No action required now. No exact completion date is offered.</small></div>${btn('No immediate remedy','none','',true)}`:`<div role="status"><strong>${status}</strong><small>${S.prod==='refusal'?'The schedule changed. Review the current state before retrying.':S.prod==='success'?'Simulated receipt · scheduled. The calendar has not advanced.':'Scheduling allows the next take; existing weekly costs continue.'}</small></div><div class="actions">${S.prod==='refusal'?btn('Review current state','review-prod','primary'):btn(S.prod==='pending'?'Submitting…':S.prod==='success'?'Scheduled ✓':'Schedule the shooting take','schedule','primary',S.prod==='pending'||S.prod==='success')}</div>`;
return work('V02 · PRODUCTION / '+(waiting?'FILM-018':'FILM-014'),waiting?'After the Rain':'The Glass Harbor','Exact film · '+status,body,missing?'':f);}
function person(){let cast=S.person==='celia',duplicate=S.person==='duplicate',leon=S.person==='leon';let name=leon?'Leon Hart':cast?'Celia Ward':'Mara Vale',role=(cast||leon)?'Actor':duplicate?'Craft lead':'Director',id=leon?'P-015':cast?'P-008':duplicate?'P-022':'P-004';let body=`<div class="row" style="align-items:flex-start">${portrait()}<div><div class="person-name">${name}</div><p>${role} · ${id} · ${badge(cast?'Available for this picture':'Working on The Glass Harbor')}</p><p>${cast?'A measured screen presence with a strong fit for this role.':'Engaged by your studio. The current assignment and contract remain distinct facts.'}</p><small>Fictional identity · perceived ability, not hidden potential</small></div></div><div class="rule"></div><div class="grid2"><div><h2 class="section-title">Relevant ability</h2>${kv([['Perceived role OVR',cast?'76 / 100':'81 / 100'],['Role fit',cast?'84 / 100':'Current director'],['Genre experience','Drama · established']])}<div class="ability"><span>Drama</span><div class="bar"><i style="width:78%"></i></div><strong>78</strong></div><small>Specialty display: proposed safe read-model dependency.</small></div><div><h2 class="section-title">Availability & cost</h2>${kv(cast?[['Availability','Available'],['Picture fee','$18,000'],['Proposed signing bonus','$12,000'],['Proposed weekly salary','$1,800'],['Employment overhead','$1,200 / week']]:[['Current work','The Glass Harbor'],['Weekly salary','$2,000'],['Employment overhead','$1,500 / week'],['Term remaining','12 weeks · ends Week 24']])}<small>Mock values, not selected tuning. Inspection changes nothing.</small></div></div><div class="rule"></div><h2 class="section-title">Recorded work</h2><div class="listrow"><div><strong>A Summer in Red</strong><small>Recorded credit · released 1925</small></div>${btn('Open film result','result')}</div>${btn('Show unavailable record','unavailable-person','text-link')}`;
if(S.variant==='unavailable')body=`<div class="empty"><h2>${name} is unavailable for assignment</h2><p>${id} is the exact selected record. No neighboring person has been substituted.</p><p>${leon?'Engaged on another film. You may inspect this record, but cannot add it to the draft.':'This record no longer resolves in the fixture.'}</p></div>`;
const footer=`<div><strong>Inspection only</strong><small>${S.from==='casting'?'Return to the same lead role and draft.':'Your originating film and scroll position are retained.'}</small></div><div class="actions">${cast&&S.variant!=='unavailable'?btn(S.signed?'Signed · demo receipt':'Review contract','contract','',S.actionBusy||S.signed):btn('Locate on lot','locate')}${S.from==='casting'&&S.variant!=='unavailable'?btn('Use in lead draft','use-candidate','primary'):btn('Back to task','back','primary')}</div>`;
return work('V03 · PERSON / '+id,name,role+' dossier · retained-lot inspection',body,footer);}
function casting(){const compare=S.comparison||S.variant==='compare';const empty=S.variant==='empty';const long=S.variant==='long';let body=`<div class="split"><aside><h2 class="section-title">Your company draft</h2><div class="role-slot">Director<strong class="muted"> · Mara Vale</strong></div><div class="role-slot active"><small>SELECTED ROLE</small><strong>Lead · ${S.draft}</strong></div><div class="role-slot">Antagonist · Eli Rowan</div><div class="role-slot">Support · June Sloane</div><div class="role-slot">Craft lead · Mara Vale</div><small>Two people share a name; the role and exact ID distinguish them.</small><div class="rule"></div>${kv([['Production budget','$600,000'],['Marketing','$100,000']])}<small>Uncommitted draft · not saved to a campaign.</small></aside><div><div class="row between"><h2 class="section-title">${compare?'Compare for the lead':'Lead · candidate review'}</h2>${badge('Draft intact')}</div>${empty?`<div class="empty"><h2>No relevant candidates</h2><p>No lawful assignment is offered in this fixture. Inspect the roster or return to the draft; no person will be auto-hired.</p>${btn('Inspect roster example','roster-example')}</div>`:compare?`<div class="grid2">${candidate('Celia Ward','P-008',84,76,'$18,000',true)}${candidate('Leon Hart','P-015',79,83,'$24,000',false)}</div>`:`<div class="row">${portrait()}<div><div class="person-name">Celia Ward</div><p>Actor · P-008 · ${badge('Available')}</p><p>Role fit 84 · Perceived OVR 76<br>Camera test: estimate 77 (range 71–83)</p><strong>One-picture fee $18,000</strong><div class="actions" style="margin-top:14px">${btn('Review exact candidate','candidate','primary')}${btn('Compare 2 candidates','compare')}</div></div></div>`}<div class="rule"></div><div class="note"><strong>Choosing is not signing</strong>Your company, budget and comparison pins remain a draft. Greenlight rechecks availability, cost and capacity.</div>${btn(empty?'Show candidate fixture':'Show no-candidate fixture',empty?'casting':'empty-candidates','text-link')}${long?'<h2 class="section-title">Large-list fixture · 30 exact records</h2>'+Array.from({length:30},(_,i)=>'<div class="listrow"><div><strong>'+ (i===0?'Alexandra Montgomery-Winterbourne':'Candidate '+(i+1))+'</strong><small>P-L'+String(i+1).padStart(3,'0')+' · unavailable fixture · inspection only</small></div>'+btn('Inspect record','list-person-'+i)+'</div>').join(''):''}${responseTools()}</div></div>`;return work('V04 · CASTING / SCRIPT-021',long?'The Long Way Home Through the Valley of a Thousand Lanterns':'The Long Way Home','Drama · lead role · uncommitted company',body,`<div><strong>Draft commitment · $700,000</strong><small>Illustrative immediate budget. Ongoing payroll is reviewed separately.</small></div><div class="actions">${compare?btn('Back to candidates','close-compare'):''}${btn(S.castStatus==='success'?'Greenlight formed · demo':S.actionBusy?'Committing…':'Review greenlight','greenlight','primary',S.actionBusy||S.castStatus==='success')}</div>`,true);}
function candidate(name,id,fit,ovr,fee,available){return `<div class="card compare-card">${portrait()}<h2>${name}</h2><small>Actor · ${id}</small><p>${badge(available?'Available':'Unavailable · other film',available?'':'warn')}</p>${kv([['Role fit',fit],['Perceived OVR',ovr],['Camera-test estimate',available?'77 · range 71–83':'No test evidence'],['Picture fee',fee]])}<p>${available?'Fits the role; this is not a guarantee of performance.':'Currently engaged. Viewing this record cannot assign this person.'}</p>${btn('Review this candidate',available?'candidate':'unavailable-leon','primary')}</div>`;}
function building(){const detail=['detail','construction','operational','lab'].includes(S.variant),invalid=S.variant==='invalid'||S.placement==='invalid';let body;if(detail){const lab=S.variant==='lab',construct=S.variant==='construction';body=`<div class="grid2"><div><div class="site"><div class="footprint">${lab?'LABORATORY':'STAGE 07'}<br>4 × 3 cells</div></div><small>Original schematic · footprint illustration</small></div><div>${badge(construct?'◷ Under construction':'● Operational',construct?'warn':'')}<h2 class="section-title" style="margin-top:15px">${lab?'Research Laboratory':'Soundstage 07'}</h2>${kv([['Facility identity',lab?'FAC-LAB-01':'FAC-STAGE-07'],['Worksite',construct?'Construction site':'Studio lot'],['Completion',construct?'1926 · Week 18 (mock)':'Completed'],['Weekly operating cost',lab?'$3,000':'$2,000']])}<p>${construct?'Not yet available for production. Opening this record does not accelerate work.':lab?'Manage research opens the P13B-owned department. This prototype does not design that workflow.':'Operational facility; capabilities belong to this exact stage.'}</p></div></div><div class="rule"></div><div class="actions">${btn('Show construction state','construction')}${btn('Show operational state','operational')}${btn('Laboratory entry style','lab')}${btn('Open catalogue & placement','placement')}</div>`;
return work('V05 · SELECTED FACILITY',lab?'Research Laboratory':'Soundstage 07','Inspection · construction is not operational capability',body,`<div><strong>${construct?'Work is in progress':'One clear local action'}</strong><small>No physical-job cancellation is implemented by this prototype.</small></div>${btn(lab?'Manage research ↗':'Locate this facility',lab?'lab-static':'locate','primary')}`);}
body=`<div class="split"><aside><h2 class="section-title">Facilities</h2>${btn('<strong>Soundstage</strong><small>4 × 3 cells · production space</small>','valid','choice selected')}${btn('<strong>Research Laboratory</strong><small>Inspect shared card styling</small>','lab','choice')}<div class="rule"></div><small>Selecting a catalogue item does not buy it. The placement quote owns price and constraints.</small></aside><div><div class="row between"><h2 class="section-title">Soundstage · placement preview</h2>${badge(invalid?'× Invalid position':'✓ Valid position',invalid?'bad':'')}</div><div class="site ${invalid?'invalid':''}"><div class="boundary"></div><div class="footprint">4 × 3 footprint<br>${invalid?'× Not here':'✓ Fits here'}</div></div><div class="actions" style="margin-top:12px">${btn('Choose valid cell','valid')}${btn('Choose invalid cell','invalid')}</div><div class="rule"></div>${kv([['Capital cost','$480,000'],['Cash after commitment','$2,000,000'],['Construction','6 weeks · ready Week 18'],['Operating cost after completion','$2,000 / week']])}<div class="note ${invalid?'bad':''}" style="margin-top:16px"><strong>${invalid?'Two constraints block this position':'Review before you build'}</strong>${invalid?'Footprint crosses the boundary. Required access space is occupied. Choose another cell; no charge has been made.':'This commits construction at the selected site. The stage becomes operational only when work completes.'}</div></div></div>`;
return work('V05 · BUILD / QUOTE EXAMPLE','Make room for the next picture','Fictional price and site · not tuning',body,`<div><strong>${invalid?'Cannot build here':'Quote · $480,000'}</strong><small>${invalid?'Boundary and access constraints must both clear.':'6 weeks of construction · $2,000/week after completion'}</small></div><div class="actions">${btn('Cancel placement','cancel-placement')}${btn('Review construction','build-review','primary',invalid)}</div>`,true);}
function finance(){const industry=S.variant==='industry',drill=S.variant==='drill';if(industry||drill){return work('V06 · INDUSTRY / PUBLIC RECORD',drill?'Northstar Pictures':'Hollywood, in public','As of 1926 · Week 12 · fictional records',`<div class="tabs">${btn('Studio charts','industry','active')}${btn('Movie charts · static example','static-movies')}${btn('Industry pulse · static example','static-pulse')}</div><div class="note"><strong>Public outcomes, not private forecasts</strong>Figures below describe recorded public gross. They do not disclose a rival’s revenue, cash, research plans or future films.</div><div class="rule"></div>${drill?`<div class="grid2"><div>${kv([['Studio','Northstar Pictures · ST-02'],['Active productions','2 publicly announced'],['Sound adoption','1 operational receipt']])}</div><div><h2 class="section-title">Latest recorded film</h2><strong>The Silver Mile</strong><p>Public gross to date · $920,000</p><small>The theatrical run remains active. Final total unavailable.</small></div></div>`:`${[['Northstar Pictures','ST-02','3 recorded releases'],['Westhaven Pictures','ST-01 · Your studio','2 recorded releases'],['Crown Hill Studio','ST-03','1 recorded release']].map(([n,id,d])=>`<div class="listrow"><div><strong>${n}</strong><small>${id} · ${d}</small></div>${btn(n==='Northstar Pictures'?'Open studio record':'Inspect static record',n==='Northstar Pictures'?'industry-drill':n==='Westhaven Pictures'?'studio-westhaven':'studio-crown')}</div>`).join('')}`}<div class="rule"></div><h2 class="section-title">Recorded context</h2><p>Authored starting history is labeled “Before this campaign.” Unavailable evidence remains unavailable rather than being displayed as zero.</p>`, `<div><strong>Return path · ${drill?'Industry › Studio charts':'Finance › Overview'}</strong><small>Tab, period, scroll and focus remain in the navigation context.</small></div>${btn('‹ Back to '+(drill?'Industry':'Finance'),'back','primary')}`);}
return work('V06 · ADMINISTRATION / FINANCE','The studio’s working picture','Last completed week · 1926, Week 11 · illustrative ledger',`<div class="tabs">${btn('Overview','finance','active')}${btn('Payroll','payroll')}${btn('Operations','facility-detail')}${btn('Films','result')}${btn('Upcoming','upcoming')}</div><div class="grid3"><div><div class="eyebrow">Cash now</div><div class="metric">$2,480,000</div><small>Available balance</small></div><div><div class="eyebrow">Last week · net movement</div><div class="metric">−$26,000</div><small>Recorded cash movement</small></div><div><div class="eyebrow">At current pacing</div><div class="metric">95 weeks</div><small>Conditional runway · not a guarantee</small></div></div><div class="rule"></div><div class="grid2"><div><h2 class="section-title">Where last week’s cash went</h2>${kv([['Payroll & overhead','−$18,000'],['Facility operations','−$8,000'],['Other recorded movement','$0']])}${btn('Explain payroll → person','profile-mara','text-link')}<small>Illustrative complete-week categories. No projected receipts included.</small></div><div><h2 class="section-title">Weekly operating outflow</h2><div class="chart">${[18,23,25,26].map((n,i)=>`<div class="chart-col"><span>$${n}k</span><i style="height:${n*3}px"></i><small>W${8+i}</small></div>`).join('')}</div><small>Mock recorded costs · dollars per week</small></div></div><div class="rule"></div><div class="note"><strong>Upcoming: Mara Vale’s term ends Week 24</strong>Review the exact person’s contract before making a commitment. This is a fixture of an authoritative deadline route.</div>`, `<div><strong>Coverage: this studio’s recorded finances</strong><small>Rival private accounts are not available here.</small></div>${btn('Open public Industry','industry','primary')}`);}
function saveLocked(){return ['pending','unresolved'].includes(S.saveStatus);}
function campaigns(){const locked=saveLocked();return work('V07 · STUDIO MENU / CAMPAIGN LIBRARY','Keep the story you are building','All campaign records below are fictional and live only in memory.',`<div class="note"><strong>ACTIVE · ${esc(S.campaign)}</strong>${S.campaign==='Unnamed current campaign'?'Unsaved progress · use Save As to create a named copy.':'Simulated named copy · no real data was written.'}</div><div class="rule"></div><div class="row between"><h2 class="section-title">Choose a saved world</h2><small>Selection alone does not load</small></div>${[['Harbor — rehearsal','DEMO-A · 1926 · Week 8'],['Westhaven — opening','DEMO-B · 1920 · Week 1']].map(([n,id])=>btn(`<strong>${S.selected===n?'✓ ':''}${n}</strong><small>${id} · ${S.selected===n?'SELECTED TARGET':'Saved fixture'}</small>`,'select-'+(n.startsWith('Harbor')?'a':'b'),'choice campaign-row '+(S.selected===n?'selected':''))).join('')}<div class="actions" style="margin:15px 0">${btn('Save active campaign','save-active','',locked)}${btn('Save As…','save-as','primary',locked)}${btn('Rename selected…','rename','',locked)}${btn('Delete selected…','delete','danger',locked)}</div><div class="rule"></div>${locked?`<div class="note"><strong>Save As · ${S.saveStatus}</strong>Resolve the existing operation before another campaign change. ${btn('View existing operation','save-status','text-link')}</div>`:''}<div class="preferences"><div><strong>Reading preference</strong><br><small>Shared presentation setting · prototype only</small></div><label for="text-size">Text <select id="text-size"><option ${S.text===100?'selected':''}>100%</option><option ${S.text===150?'selected':''}>150%</option><option ${S.text===200?'selected':''}>200%</option></select></label></div>${responseTools()}`,`<div><strong>Selected: ${esc(S.selected)}</strong><small>Loading or leaving requires an explicit review.</small></div><div class="actions">${btn('Quit to Desktop…','leave-quit','',locked)}${btn('Load selected…','leave','primary',locked)}</div>`,true);}
function result(){return work('V08 · FILM RESULT / RELEASE-006','A Summer in Red','Released 1925 · recorded film, fictional example',`<div class="grid2"><div class="film-poster"><small>WESTHAVEN PICTURES PRESENTS</small><h2>A Summer<br>in Red</h2><small>ORIGINAL POSTER PLACEHOLDER · DRAMA</small></div><div><div class="eyebrow">Recorded outcome</div><div class="grid2" style="margin-top:16px"><div class="result-stat"><h2 class="section-title">Critics</h2><div class="metric">78 / 100</div><small>Actual recorded score</small></div><div class="result-stat"><h2 class="section-title">Audience</h2><div class="metric">82 / 100</div><small>Actual recorded score</small></div></div><p>The audience response and critic assessment remain separate. Neither is a universal quality score.</p></div></div><div class="rule"></div><div class="grid2"><div><h2 class="section-title">Business record</h2>${kv([['Public gross · completed run','$1,240,000'],['Studio receipts · recorded','$680,000'],['Production & marketing paid','$500,000'],['Direct difference','$180,000']])}<small>Direct difference excludes whole-studio payroll and operating costs. Mock values, not a profit claim about real play.</small></div><div><h2 class="section-title">What was expected</h2>${kv([['Greenlight total-gross forecast','$1.0m–$1.4m'],['Forecast provenance','Frozen at greenlight'],['Historical camera-test evidence','Unavailable']])}<p>The forecast is retained evidence of the original decision. It has not been recomputed from the result.</p></div></div><div class="rule"></div><h2 class="section-title">People & attribution</h2><div class="listrow"><div><strong>Mara Vale · Director · P-004</strong><small>Recorded credit, not a current assignment</small></div>${btn('Open exact profile','profile-mara')}</div>`, `<div><strong>Released record · no current lot worksite</strong><small>History retains film identity and recorded attribution.</small></div>${btn('Open studio history','history','primary')}`);}
function components(){return work('C01 · SHARED LANGUAGE','The studio desk','Reference tokens · logical pixels · no imported fonts or artwork',`<h2 class="section-title">Warm, opaque surfaces. Precise actions.</h2><div class="swatches">${[['Paper','#f6f1e5'],['Ink','#233a33'],['Pine','#224e43'],['Brass','#d8b56c'],['Focus','#175db5'],['Refusal','#942f29']].map(([n,c])=>`<div class="swatch"><i style="background:${c}"></i><strong>${n}</strong><br><small>${c}</small></div>`).join('')}</div><div class="rule"></div><div class="grid2"><div><div class="eyebrow">TYPE · GEORGIA + ARIAL</div><h2 style="font:30px Georgia;margin:8px 0">The Glass Harbor</h2><p>Body 16 / 23.2 · Supporting 13 / 18.9<br>Section 22 / 29 · Eyebrow 12 / 17.4</p><small>Use available system fonts. No font downloads.</small></div><div>${kv([['Control target','44px minimum height'],['Panel radius / border','8px / 1px'],['Gutters / content padding','24px / 24px'],['Focus','3px ring + 3px offset']])}</div></div><div class="rule"></div><div class="grid3">${[['Idle','state-chip'],['Hover','state-chip hover-state'],['Keyboard focus','state-chip focus-state'],['Pressed','state-chip pressed'],['✓ Selected','state-chip selected-state']].map(([n,c])=>`<div class="${c}">${n}</div>`).join('')}${btn('Unavailable','none','',true)}</div><div class="grid2" style="margin-top:18px"><div class="note"><strong>Disabled · no Post capacity</strong>No immediate remedy; wait for the occupying film.</div><div class="note"><strong>Pending · scheduling…</strong>Request acknowledged. Do not submit again.</div><div class="note good"><strong>Simulated authoritative success</strong>Take scheduled. Calendar unchanged.</div><div class="note bad"><strong>Refusal · schedule changed</strong>Review the current state before retrying.</div><div class="note bad"><strong>Disconnected / unresolved</strong>The outcome is not known. Closing this view cannot cancel it.</div><div class="note"><strong>Safe retry</strong>Retry the same request to recover its receipt.</div></div>`, `<div><strong>Icons always travel with labels</strong><small>Words and state shapes carry meaning without color.</small></div>${btn('Preview a focused dialog','save-as','primary')}`,true);}
function alternatives(){return work('D00 · COMPOSITION STUDY','Two compositions, one recommendation','Original schematic proposals · same product, different allocation of attention',`<div class="grid2"><div><div class="alt-frame"><div class="alt-top">STUDIO · date / pause · cash · campaign</div><div class="alt-right">Films<br>• Decision<br>• Waiting</div><div class="alt-bottom">Selected stage<br>Open production →</div></div><div class="alt-title">A · Studio desk ${badge('Recommended')}</div><p>Light peripheral surfaces keep the lot usable. Substantial dossiers and larger comparison workspaces open deliberately, with a retained place to return.</p></div><div><div class="alt-frame"><div class="alt-top">STUDIO · date / pause · cash</div><div class="alt-left">PRODUCTIONS<br><hr>Company<br><hr>Finance<br><hr>Facility details<br><hr>Current decisions</div></div><div class="alt-title">B · Permanent ledger</div><p>A permanent 40% management column is easy to scan, but makes the lot secondary and turns routine play into a persistent management sheet.</p></div></div><div class="note"><strong>Develop direction A</strong>It fits the original-The-Movies-led goal while giving casting, contracts and finances enough readable space. The eight boards use this one direction.</div>`, `<div><strong>World-first, not world-only</strong><small>Product choices and simulation rules are preserved.</small></div>${btn('See the recommended lot','home','primary')}`,true);}
function render(){const oldScroll=$('#game').dataset.screen===S.screen?($('#scroll')?.scrollTop||0):0;document.body.classList.toggle('annotated',params.has('annotated'));document.body.classList.toggle('large',S.text>100);document.body.classList.toggle('stress',innerWidth<=1280);document.documentElement.style.setProperty('--size',S.text/100);$('#board').value=S.screen==='finance'?'finance':S.screen;const content=({home,production,person,casting,building,finance,campaigns,result,components,alternatives}[S.screen]||home)();$('#game').innerHTML=hud()+`<div class="stage">${content}</div>`+nav();$('#game').dataset.screen=S.screen;if($('#scroll'))$('#scroll').scrollTop=oldScroll;const n=notes[S.screen]||notes.home;$('#annotations').innerHTML=`<div class="eyebrow" style="color:#d9bc79">ANNOTATED DESIGN VIEW</div><h2>${n[0]}</h2>${n.slice(1).map((x,i)=>`<h3><span class="annotation-number">${i+1}</span>${x.slice(0,1)}</h3><p>${x.slice(2)}</p>`).join('')}<hr><p>1440×900 reference composition. Logical dimensions and reflow rules are in SPECIFICATION.md.</p><strong>PROPOSED / MOCK DATA<br>NOT IMPLEMENTED</strong>`;}
function currentContext(){return {screen:S.screen,variant:S.variant,person:S.person,from:S.from,scroll:$('#scroll')?.scrollTop||0,focus:document.activeElement?.dataset?.act};}
function go(screen,variant='',extra={}){trail.push(currentContext());S.screen=screen;S.variant=variant;Object.assign(S,extra);render();requestAnimationFrame(()=>$('.work-head button')?.focus());}
function back(){if(dialog){if(['pending','unresolved','action-pending'].includes(dialog.type)){toast('Closing the view does not cancel the submitted demo operation.');}closeModal();return;}const c=trail.pop();if(c){Object.assign(S,c);render();requestAnimationFrame(()=>{if($('#scroll'))$('#scroll').scrollTop=c.scroll;document.querySelector(`[data-act="${c.focus}"]`)?.focus({preventScroll:true});});}else{S.screen='home';S.variant='mature';render();}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function closeModal(){dialog=null;$('#modal-root').innerHTML='';$('#game').inert=false;$('.demo-bar').inert=false;originFocus?.focus({preventScroll:true});}
function modal(type){if(!dialog)originFocus=document.activeElement;dialog={type};let title='',body='',foot='';const cancel=btn('Cancel','close-modal');
if(type==='contract'){title='Review Celia’s contract';body=`<p>Employment is a new commitment. It is separate from choosing Celia for a film.</p>${kv([['Person','Celia Ward · P-008'],['Term','52 weeks'],['Signing bonus now','$12,000'],['Salary','$1,800 / week'],['Employment overhead','$1,200 / week'],['Cash after signing','$2,468,000']])}<div class="note">Employment costs continue while idle. These fixture terms are not gameplay tuning.</div>`;foot=cancel+btn('Stage signing request','sign','primary');}
if(type==='greenlight'){title='Review this picture’s commitment';body=`<strong>The Long Way Home · SCRIPT-021</strong><p>Lead: ${esc(S.draft)} · the rest of your draft is intact.</p>${kv([['Production budget','$600,000'],['Marketing','$100,000'],['Total immediate commitment','$700,000'],['Mock cash after','$1,780,000'],['Existing weekly company costs','$6,400 / week']])}<div class="note"><strong>Admission must be rechecked</strong>This fixture represents a formed package. In the game, a queued package has no production identity, budget or talent commitment until admitted and revalidated.</div>`;foot=btn('Back to draft','close-modal')+btn('Stage greenlight commitment','commit-cast','primary');}
if(type==='build'){title='Commit this construction?';body=`<p>Soundstage · selected 4 × 3 site</p>${kv([['Capital cost now','$480,000'],['Cash after','$2,000,000'],['Build duration','6 weeks'],['Operating cost after completion','$2,000 / week']])}<p>Construction is not operational capacity. Cancel here leaves the preview uncommitted.</p>`;foot=cancel+btn('Stage construction','commit-build','primary');}
if(type==='leave'){title='Keep this progress before leaving';body=`<p>Active world: <strong>${esc(S.campaign)}</strong></p><div class="note"><strong>Unsaved progress</strong>Save As creates and opens a named copy. Uncommitted casting form drafts are not included.</div><p>Your intended next task: ${S.leaveTask||'Load Harbor — rehearsal'}. Nothing leaves this world yet.</p>`;foot=cancel+btn('Review discard instead','discard-review','danger')+btn('Save As…','save-as','primary');}
if(type==='name'){title='Name a copy of this campaign';body=`<label class="field"><span>Campaign name</span><input id="campaign-name" maxlength="64" value="${esc(S.name)}" autocomplete="off"></label><small>A campaign label does not rename the studio.</small><div class="note" style="margin-top:16px"><strong>What Save As will do</strong>Copy current simulation progress and open the copy. Keep the source record. Discard unsaved casting form drafts only after an accepted operation.</div>`;foot=cancel+btn('Review named copy','name-review','primary');}
if(type==='copy-review'||type==='overwrite'){title=type==='overwrite'?'Review overwrite':'Review the named copy';body=`${kv([['Source',esc(S.campaign)],['Destination',esc(S.name)],['After completion','New copy is active']])}<div class="note ${type==='overwrite'?'bad':''}"><strong>${type==='overwrite'?'An existing name matches':'Copy progress; discard form drafts'}</strong>${type==='overwrite'?'This will replace the selected named record with current progress. The source record remains separate.':'All changes are fictional. Real implementation must show current authoritative copy and draft consequences.'}</div>${responseTools()}`;foot=cancel+btn(type==='overwrite'?'Stage overwrite':'Stage Save As','submit-save',type==='overwrite'?'danger':'primary');}
if(type==='pending'){title='Saving named copy…';body=`<p><strong>${esc(S.name)}</strong></p><div class="note"><strong>Request acknowledged · waiting for receipt</strong>No completion is claimed. Repeated submission is disabled.</div><p>Closing this view does not cancel the submitted operation.</p>`;foot=btn('Close view','close-modal')+btn('Saving…','none','primary',true);}
if(type==='unresolved'){title='Save As outcome is unresolved';body=`<p>${esc(S.name)}</p><div class="note bad"><strong>The response did not arrive</strong>The operation may have completed. Retry the same request to recover its receipt; do not create another copy.</div><p>No real storage operation occurred in this demo.</p>`;foot=btn('Close view','close-modal')+btn('Retry same operation','retry-save','primary');}
if(type==='save-refused'){title='Save As refused';body='<div class="note bad"><strong>The destination changed</strong>No success is claimed. Review the current name and consequences before a new submission.</div>';foot=btn('Close view','close-modal')+btn('Review name again','save-as','primary');}
if(type==='receipt'){title='Named copy saved · simulated receipt';body=`<div class="note good"><strong>${esc(S.name)} is the active copy</strong>Source record preserved. Form drafts were excluded. This is a staged design receipt, not native persistence evidence.</div><p>You have not yet continued to ${S.leaveTask||'Load Harbor — rehearsal'}.</p>`;foot=btn('Stay in this copy','stay')+btn('Review original leave task','continue-review','primary');}
if(type==='continue'){title='Continue to the original task?';body=`${kv([['Active now',esc(S.name)],['Next task',esc(S.leaveTask||'Load Harbor — rehearsal')]])}<p>This is a new, explicit continuation review. Implementation must recheck current authority, selected target and any new unsaved progress.</p>`;foot=btn('Stay in this copy','stay')+btn('Continue · demo only','finish-leave','primary');}
if(type==='discard'){title='Discard progress and leave?';body='<div class="note bad"><strong>This loses unsaved progress</strong>A real implementation must disclose current progress and form-draft loss. This prototype will only reset fictional navigation.</div>';foot=cancel+btn('Discard demo progress','discard-demo','danger');}
if(type==='rename'){title='Rename selected campaign';body=`<p>Selected target: ${esc(S.selected)}</p><label class="field"><span>New label</span><input id="rename-name" value="${esc(S.selected)}" maxlength="64"></label><p>This changes only this mock label. It does not change game authority.</p>`;foot=cancel+btn('Rename demo record','rename-commit','primary');}
if(type==='delete'){title='Delete selected campaign?';body=`<p><strong>${esc(S.selected)}</strong></p><div class="note bad">Only this selected mock record is targeted. A real implementation must preserve current-world behavior and require its authoritative destructive review.</div>`;foot=cancel+btn('Stage delete example','delete-commit','danger');}
if(type==='action-pending'){title=S.pendingKind==='sign'?'Signing request pending…':'Greenlight commitment pending…';body='<div class="note"><strong>Staged request acknowledged</strong>Waiting for a simulated response. Another submission is disabled. Closing this view does not cancel the submitted request.</div>';foot=btn('Close view','close-modal')+btn('Waiting for receipt…','none','primary',true);}
if(type==='static'){title='Static design example';body=`<p>${S.staticMessage||'This destination is outside the three interactive journeys. The linked board illustrates the intended presentation.'}</p><div class="note">PROPOSED PRESENTATION ONLY · no gameplay behavior is being simulated.</div>`;foot=btn('Back to previous view','close-modal','primary');}
$('#modal-root').innerHTML=`<div class="modal-shade"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="modal-head">${idline('PROPOSED / MOCK DATA · '+type.toUpperCase())}<h2 id="dialog-title">${title}</h2></header><div class="modal-body">${body}</div><footer class="modal-foot">${foot}</footer></section></div>`;$('#game').inert=true;$('.demo-bar').inert=true;requestAnimationFrame(()=>$('.modal input')?$('.modal input').focus():$('.modal button')?.focus());}
function staticExample(msg){S.staticMessage=msg;modal('static');}
function showSaveStatus(){modal(({success:'receipt',refused:'save-refused'})[S.saveStatus]||S.saveStatus);}
function saveDemo(retry=false){if(S.saveStatus==='pending'||(S.saveStatus==='unresolved'&&!retry)){showSaveStatus();return;}if(retry&&S.saveStatus!=='unresolved')return;const outcome=S.outcome;S.saveStatus='pending';render();modal('pending');saveTimer=setTimeout(()=>{const observing=dialog?.type==='pending';if(outcome==='unresolved'&&!retry){S.saveStatus='unresolved';}else if(outcome==='refusal'&&!retry){S.saveStatus='refused';}else{S.saveStatus='success';S.campaign=S.name;}render();if(observing)showSaveStatus();else toast('Save As · '+S.saveStatus+'. Open its status beside the active campaign.');},1100);}

function act(a){if(a==='save-status'){showSaveStatus();return;}if(saveLocked()&&['save-active','save-as','rename','delete','leave','leave-quit','rename-commit','delete-commit','finish-leave','discard-demo'].includes(a)){showSaveStatus();return;}if(a.startsWith('list-person-')){staticExample('Exact fictional record P-L'+String(Number(a.split('-').pop())+1).padStart(3,'0')+' · unavailable. No assignment or neighboring-record substitution.');return;}if(a==='back'){back();return;}if(a==='close-modal'){back();return;}if(['home','production','casting','person','building','finance','campaigns','result','components','alternatives'].includes(a)){go(a,a==='home'?'mature':'');return;}switch(a){case 'early':case 'mature':S.variant=a;render();break;case 'pause':S.paused=!S.paused;render();toast('Time-control presentation only. No calendar advance is simulated.');break;case 'speed':toast('Speed selection is outside the three journeys. No simulation clock runs.');break;case 'wait':go('production','waiting');break;case 'missing':go('production','missing');break;case 'profile-mara':case 'profile-duplicate':case 'profile-celia':go('person','',{person:a==='profile-duplicate'?'duplicate':a==='profile-celia'?'celia':'mara',from:S.screen});break;case 'candidate':go('person','',{person:'celia',from:'casting'});break;case 'unavailable-leon':go('person','unavailable',{person:'leon',from:'casting'});break;case 'unavailable-person':go('person','unavailable',{person:'celia',from:S.screen});break;case 'compare':S.comparison=true;S.variant='compare';render();break;case 'close-compare':S.comparison=false;S.variant='';render();break;case 'use-candidate':S.draft='Celia Ward';back();toast('Celia is selected in the lead draft. No contract was signed.');break;case 'empty-candidates':S.variant='empty';render();break;case 'contract':if(S.actionBusy)modal('action-pending');else if(S.signed)staticExample(S.actionReceipt);else modal('contract');break;case 'greenlight':if(S.actionBusy)modal('action-pending');else if(S.castStatus==='success')staticExample(S.actionReceipt);else modal('greenlight');break;case 'schedule':S.prod='pending';render();timer=setTimeout(()=>{S.prod=S.outcome==='success'?'success':'refusal';render();},950);break;case 'review-prod':S.prod='ready';render();break;case 'sign':case 'commit-cast':if(S.actionBusy)return;S.actionBusy=true;S.pendingKind=a;modal('action-pending');render();actionTimer=setTimeout(()=>{S.actionBusy=false;if(a==='commit-cast')S.castStatus=S.outcome==='success'?'success':'refusal';if(a==='sign'&&S.outcome==='success')S.signed=true;render();S.actionReceipt=(S.outcome==='success'?'Simulated receipt: '+(a==='sign'?'contract signed for the reviewed person and terms.':'greenlight formed for the exact reviewed draft.')+' No real money or game state changed.':'Simulated refusal: availability changed. The original draft is retained. Review the exact candidate before retrying.');if(dialog?.type==='action-pending')staticExample(S.actionReceipt);else toast(S.actionReceipt);},1000);break;case 'facility-detail':if(S.screen==='production'&&S.variant==='waiting')staticExample('Production Post · FAC-POST-01 · Occupied by another film. This is the exact supporting facility. No immediate remedy or completion date is provided; return to After the Rain unchanged.');else go('building','detail');break;case 'construction':case 'operational':case 'lab':go('building',a);break;case 'placement':go('building','');break;case 'valid':case 'invalid':S.placement=a;S.variant=a;render();break;case 'cancel-placement':go('building','detail');toast('Uncommitted placement cancelled. No mock charge.');break;case 'build-review':modal('build');break;case 'commit-build':closeModal();go('building','construction');toast('Simulated construction receipt. Facility is not operational yet.');break;case 'lab-static':staticExample('Manage research routes to the existing Laboratory owner. Staffing, research choices, funding and the department workspace remain P13B-owned and are intentionally not redesigned here.');break;case 'locate':toast('Locate would frame this exact body and retain return context. Camera movement is a static example in this prototype.');break;case 'industry':go('finance','industry');break;case 'studio-westhaven':case 'studio-crown':staticExample((a==='studio-westhaven'?'Westhaven Pictures · ST-01 · Your studio · 2 recorded releases':'Crown Hill Studio · ST-03 · 1 recorded release')+'. Exact fictional public record. Its deeper dossier is outside prototype coverage; no other studio is substituted.');break;case 'industry-drill':go('finance','drill');break;case 'payroll':staticExample('Payroll drill-down: current salary and employment overhead are distinct. The person link opens the exact existing Profile; this destination is shown as a static Finance example.');break;case 'upcoming':staticExample('Upcoming example: a dated renewal warning opens Mara Vale · P-004. It preserves Finance period and scroll, and never creates an automatic renewal.');break;case 'history':staticExample('Studio History keeps the exact film ID, recorded credit, event date and attribution. Back returns to A Summer in Red. No new history or outcome is generated.');break;case 'static-movies':case 'static-pulse':case 'roster-example':staticExample('This destination uses the existing published owner. It is a labeled static example outside the three interactive journeys; no missing candidates or outcomes are invented.');break;case 'select-a':S.selected='Harbor — rehearsal';render();break;case 'select-b':S.selected='Westhaven — opening';render();break;case 'leave':S.leaveTask='Load '+S.selected;modal('leave');break;case 'leave-quit':S.leaveTask='Quit to Desktop';modal('leave');break;case 'save-active':if(S.campaign==='Unnamed current campaign')modal('name');else staticExample('Save active campaign: operation-specific pending and receipt states follow the same campaign owner. This static example does not write a file.');break;case 'save-as':modal('name');break;case 'name-review':{const val=$('#campaign-name').value.trim();if(!val){$('#campaign-name').setAttribute('aria-invalid','true');toast('Enter a visible campaign name before continuing.');return;}S.name=val;modal(['harbor — rehearsal','westhaven — opening'].includes(val.toLowerCase())?'overwrite':'copy-review');break;}case 'submit-save':saveDemo();break;case 'retry-save':saveDemo(true);break;case 'continue-review':modal('continue');break;case 'stay':closeModal();S.screen='campaigns';render();break;case 'finish-leave':closeModal();S.screen='home';S.variant='mature';render();toast('Original leave task completed as a navigation demonstration only. No campaign was loaded and no app quit.');break;case 'discard-review':modal('discard');break;case 'discard-demo':closeModal();S.screen='home';render();toast('Only fictional navigation was reset.');break;case 'rename':case 'delete':modal(a);break;case 'rename-commit':S.selected=$('#rename-name').value;closeModal();render();toast('Renamed mock record · simulated receipt.');break;case 'delete-commit':closeModal();toast('Delete example staged · no filesystem or real record operation.');break;default:toast('This is a labeled static design control.');}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(b&&!b.disabled)act(b.dataset.act);});
document.addEventListener('change',e=>{if(e.target.id==='outcome')S.outcome=e.target.value;if(e.target.id==='text-size'){S.text=parseInt(e.target.value);render();}if(e.target.id==='board')go(e.target.value);});
$('#reset').addEventListener('click',()=>{history.replaceState(null,'',location.pathname);params.delete('state');params.delete('screen');params.delete('text');reset();toast('Demo reset. No saved state exists.');});
document.addEventListener('keydown',e=>{if(dialog){if(e.key==='Escape'){e.preventDefault();back();return;}if(e.key==='Tab'){const els=[...document.querySelectorAll('.modal button:not(:disabled),.modal input,.modal select')];const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}if(e.key==='Enter'&&e.target.id==='campaign-name'){e.preventDefault();act('name-review');}return;}if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(e.key==='Escape'){e.preventDefault();back();}});
reset();
